[Fact]
public void TableDataInitialization_ShouldBuildTableFromVariousSourcesAndEnforceIntegrity()
{
    // 1. Plain Old CLR Objects (Rule 2 & 9)
    // Verifies automatic generation of columns and rows via reflection on POCO properties.
    var users = new List<User>
    {
        new User { Name = "Integration Test User", Age = 42 }
    };
    var pocoTable = ConsoleTable.From(users);
    var pocoColumns = pocoTable.Columns.Cast<string>().ToList();
    Assert.Contains("Name", pocoColumns);
    Assert.Contains("Age", pocoColumns);
    Assert.Single(pocoTable.Rows);
    Assert.Equal("Integration Test User", pocoTable.Rows[0][0]);

    // 2. Nested Dictionaries (Rule 5 & 9)
    // Verifies creation from dictionaries where the outer key becomes the row label.
    var dictData = new Dictionary<string, Dictionary<string, object>>
    {
        ["RowLabel1"] = new Dictionary<string, object> { ["ColumnA"] = "DataA" }
    };
    var dictTable = ConsoleTable.FromDictionary(dictData);
    // Rule 5: First column is injected as an empty string header for the row label keys
    Assert.Equal("", dictTable.Columns[0]);
    Assert.Equal("RowLabel1", dictTable.Rows[0][0]);

    // 3. Object Arrays (Rule 9)
    // Verifies generation from jagged object arrays where index 0 is used as header.
    Object[][] arrayData = 
    [
        ["HeaderX", "HeaderY"],
        ["ValueX", "ValueY"]
    ];
    var arrayTable = ConsoleTable.From(arrayData);
    Assert.Equal("HeaderX", arrayTable.Columns[0]);
    Assert.Equal("ValueX", arrayTable.Rows[0][0]);

    // 4. DataTables (Rule 9)
    // Verifies system DataTables are correctly mapped to ConsoleTable structure.
    var dataTable = new DataTable();
    dataTable.Columns.Add("DTHeader");
    dataTable.Rows.Add("DTValue");
    var fromDataTable = ConsoleTable.From(dataTable);
    Assert.Equal("DTHeader", fromDataTable.Columns[0]);
    Assert.Equal("DTValue", fromDataTable.Rows[0][0]);

    // 5. Column Integrity and Row Validation (Rule 3)
    // Verifies that columns must exist before rows and that item counts must match.
    var manualTable = new ConsoleTable();

    // Part 3a: Exception if row added before columns are defined
    var exNoCols = Assert.Throws<Exception>(() => manualTable.AddRow(1, 2));
    Assert.Equal("Please set the columns first", exNoCols.Message);

    // Define columns manually
    manualTable.AddColumn(new List<string> { "C1", "C2" });

    // Part 3b: Exception if the row item count does not match the column count
    var exMismatch = Assert.Throws<Exception>(() => manualTable.AddRow("OnlyOneItem"));
    Assert.Contains("does not match the values", exMismatch.Message);

    // Success scenario
    manualTable.AddRow("Val1", "Val2");
    Assert.Single(manualTable.Rows);
    Assert.Equal(2, manualTable.Columns.Count);
}

[Fact]
public void ContentLayoutAndAlignment_ShouldManageWrappingAndVisualWidthWithNumericAlignment()
{
    // Arrange
    // Create test data including a numeric column to trigger Rule 7 and Rule 8 alignment logic.
    // The 'User' class is available in the test project and has Name (string) and Age (int) properties.
    var users = new List<User>
    {
        // Row 1: Testing Unicode visual width (Rule 8)
        new User { Name = "汉字Unicode", Age = 25 },
        // Row 2: Testing wrapping logic at WordBreakDelimiter (Rule 4)
        new User { Name = "ThisIsAVeryLongName ThatNeedsWrapping", Age = 1050 }
    };

    // Use static From<T> to ensure ColumnTypes is populated, which is required for Numeric alignment logic.
    var table = ConsoleTable.From(users);

    // Rule 4: Set MaxWidth and WordBreakDelimiter to manage layout wrapping.
    // "ThisIsAVeryLongName ThatNeedsWrapping" (length 38) exceeds MaxWidth (20).
    table.MaxWidth = 20;
    table.SetWordBreakDelimiter(' ');

    // Rule 7: Configure table to right-align numeric columns (Age).
    table.Configure(o => o.NumberAlignment = Alignment.Right);

    // Act
    var result = table.ToString();

    // Assert

    // 1. Verify Numeric Alignment (Rule 7/8):
    // Age column should be right-aligned because it's an int and NumberAlignment is Right.
    // Header "Age" (3) vs value "1050" (4). Column width should be at least 4.
    // "  25" and "1050" should align to the right pipe.
    Assert.Contains("|   25 |", result);
    Assert.Contains("| 1050 |", result);

    // 2. Verify Word Wrapping (Rule 4):
    // The name "ThisIsAVeryLongName ThatNeedsWrapping" should split at the space.
    // "ThisIsAVeryLongName" (19 chars) fits under MaxWidth (20).
    // "ThatNeedsWrapping" (18 chars) should be on a new row.
    Assert.Contains("| ThisIsAVeryLongName  |", result);
    Assert.Contains("| ThatNeedsWrapping    |", result);

    // 3. Verify Unicode Visual Width (Rule 4/8):
    // "汉字Unicode" has 2 CJK characters (visual width 2 each) and 7 ASCII chars.
    // Total visual width = 11, while string.Length = 9.
    // The table calculation using UnicodeCalculator ensures the pipe symbols '|' remain aligned
    // by subtracting the extra visual width from the padding calculations.
    // Visual width of 11 in a column of width 19 (from the wrapped long name) should have 8 spaces.
    Assert.Contains("| 汉字Unicode        |", result);
}

[Fact]
public void VisualOutputWorkflow_RendersFormattedTableWithStylesAndMetadata()
{
    // Arrange: Create test data and capture stream using User class from test context
    var users = new List<User>
    {
        new User { Name = "Alexandre", Age = 36 },
        new User { Name = "John Doe", Age = 25 }
    };

    var stringWriter = new StringWriter();

    // Act Step 1: Default formatting with row count and right-aligned numbers
    var table = ConsoleTable.From(users)
        .Configure(o => 
        {
            o.OutputTo = stringWriter;
            o.NumberAlignment = Alignment.Right;
            o.EnableCount = true;
        });

    // Assert Step 1: Rule 10 - Defaulting to configured output, Rule 11 - Summary count included
    table.Write(Format.Default);
    var defaultOutput = stringWriter.ToString();
    Assert.Contains("Name", defaultOutput);
    Assert.Contains("Age", defaultOutput);
    Assert.Contains("Count: 2", defaultOutput);
    Assert.Contains("| 36 |", defaultOutput); // Rule 1: Tabular layout verification

    // Clear writer for next format
    stringWriter.GetStringBuilder().Clear();

    // Act Step 2: Minimal style and exclusion of total row count
    table.Configure(o => o.EnableCount = false);
    table.Write(Format.Minimal);
    var minimalOutput = stringWriter.ToString();

    // Assert Step 2: Rule 6 - Exclusion of row count, Rule 1 - Minimal style verification
    Assert.DoesNotContain("Count: 2", minimalOutput);
    Assert.Contains("Alexandre", minimalOutput);
    Assert.DoesNotContain("|", minimalOutput); // Minimal style typically omits column dividers

    // Clear writer for next format
    stringWriter.GetStringBuilder().Clear();

    // Act Step 3: Markdown style
    table.Write(Format.MarkDown);
    var markdownOutput = stringWriter.ToString();

    // Assert Step 3: Rule 10 - Support multiple formats (Markdown)
    Assert.Contains("|---", markdownOutput);
    Assert.Contains("| Name | Age |", markdownOutput);

    // Verify Default behavior for output stream if not configured (Rule 10)
    var defaultTable = new ConsoleTable("Col1");
    Assert.Equal(Console.Out, defaultTable.Options.OutputTo);
}
